  <!-- Pre-rendered content -->
</div>

<script>
  // Find elements with matching data attribute
  const elements = document.querySelectorAll('[data-component="interactive-element"]');

  // Apply enhancements to each instance
  elements.forEach(element => {
    // Add event listeners
